# -*- coding: utf-8 --

import time
from robot.api import logger
from taf.rfrl.cbts.connections.rest_conn_vcu import GenericCU
from taf.internal.robot_typecasts.typecasts import time_to_seconds

LOG_HEAD = LOG_END = '*' * 8


class vCUCM(GenericCU):

    # ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def _perform_delta_recommissioning(self, delta_file, timeout=300, connection=None):
        return self.cu.perform_delta_recommissioning(delta_file=delta_file, wait_for_completion=True,
                                                     should_activate=True, timeout=timeout, connection=connection)

    def full_commissioning(self, stage_plan_file_path, plan_name="default_plan_name",
                           conn_alias='default', timeout_4_full_commission_finished=300):
        upload_plan_act_id = self.cu.upload_plan_file(path_to_plan_file=stage_plan_file_path, plan_name=plan_name,
                                                      connection=conn_alias)['action_id']
        stage_plan_id = self._verify_upload_stage_plan_action_status(upload_plan_act_id,
                                                                     conn_alias=conn_alias,
                                                                     timeout=30)
        validate_plan_act_id = self.cu.plan_validation(plan_id=stage_plan_id, connection=conn_alias)['action_id']
        self._verify_validate_stage_plan_action_status(action_id=validate_plan_act_id, plan_id=stage_plan_id,
                                                       conn_alias=conn_alias,
                                                       timeout=30)
        activate_plan_act_id = self.cu.plan_activation(plan_id=stage_plan_id,
                                                       connection=conn_alias)['id']
        self._verify_activate_stage_plan_action_status(action_id=activate_plan_act_id,
                                                       plan_id=stage_plan_id,
                                                       conn_alias=conn_alias,
                                                       timeout=time_to_seconds(timeout_4_full_commission_finished))
        time.sleep(30)

    def _verify_upload_stage_plan_action_status(self, action_id, expected_status='success',
                                                conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            upload_stage_plan_res = self.cu.get_operation_state_of_uploading_plan(operation_id=action_id,
                                                                                  connection=conn_alias)
            if upload_stage_plan_res['status'] == expected_status:
                logger.info(' {} Stage plan was uploaded successfully {}'.format(LOG_HEAD, LOG_END))
                return upload_stage_plan_res['plan_id']
            else:
                time.sleep(2)
        raise Exception('Uploading stage plan failed in the given 20s. The status is {}, error msg is {}'.format(
            upload_stage_plan_res['status'], upload_stage_plan_res['error_message']
        ))

    def _verify_validate_stage_plan_action_status(self, action_id, plan_id, expected_status='success',
                                                  conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            val_stage_plan_res = self.cu.get_operation_state_of_validating_plan(plan_id=plan_id,
                                                                                operation_id=action_id,
                                                                                connection=conn_alias)
            if val_stage_plan_res['status'] == expected_status:
                logger.info('{} Stage plan was validated successfully {}'.format(LOG_HEAD, LOG_END))
                return
            else:
                time.sleep(2)
        raise Exception('Validating stage plan failed in the given 20s. The status is {}, error msg is {}'.format(
            val_stage_plan_res['status'], val_stage_plan_res['error_message']
        ))

    def _verify_activate_stage_plan_action_status(self, action_id, plan_id,
                                                  conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            try:
                activate_stage_plan_res = self.cu.get_operation_state_of_activating_plan(plan_id=plan_id,
                                                                                         operation_id=action_id,
                                                                                         connection=conn_alias)
                if activate_stage_plan_res['status'] == 'success':
                    logger.info('{} Stage plan was activated successfully {}'.format(LOG_HEAD, LOG_END))
                    return
                elif activate_stage_plan_res['status'] == 'failure':
                    raise Exception('{} Stage Plan was activated Failed {}\n{}'.format(LOG_HEAD, LOG_END,
                                                                                       activate_stage_plan_res))
                else:
                    logger.info('{} Activating Stage plan in ongoing {}'.format(LOG_HEAD, LOG_END))
                    time.sleep(2)
            except Exception as err:
                if "service unavailable" or "connection refused" in str(err).lower():
                    logger.info(
                        '{} UM service is not available or Connection refused due to NE reset, '
                        'will retry in 2min {}'.format(LOG_HEAD, LOG_END))
                else:
                    logger.info('{} Get delta plan activation status failure {}'.format(LOG_HEAD, LOG_END))
                    logger.info(str(err))
                time.sleep(120)

        raise Exception('Activating stage plan failed in the given 20s. The status is {}, error msg is {}'.format(
            activate_stage_plan_res['status'], activate_stage_plan_res['error_message']))

    def _validate_gen_delta_plan_status(self, action_id, conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            gen_delta_plan_res = self.cu.get_action_state_of_generating_delta_plan(action_id=action_id,
                                                                                   connection=conn_alias)
            if gen_delta_plan_res['status'] == 'success':
                logger.info('{} Delta plan created successfully {}'.format(LOG_HEAD, LOG_END))
                return gen_delta_plan_res['plan_id']
            else:
                time.sleep(2)
        raise Exception('Generating Delta plan failed in the given 20s. The status is {}, error msg is {}'.format(
            gen_delta_plan_res['status'], gen_delta_plan_res['error_message']
        ))

    def _provision_vcu_delta_plan(self, operation_id, use_m2m, conn_alias='default', timeout=300):
        endtime = time.time() + timeout
        while time.time() < endtime:
            try:
                pro_delta_plan_info = self.cu.get_provision_vcu_delta_plan_status(operation_id=operation_id,
                                                                                  use_m2m=use_m2m,
                                                                                  connection=conn_alias)
                pro_delta_plan_status = pro_delta_plan_info['status']
                if pro_delta_plan_status == 'success':
                    logger.info('{} Delta plan provisioned successfully {}'.format(LOG_HEAD, LOG_END))
                    return
                elif pro_delta_plan_status == 'failure':
                    raise Exception('{} Activating delta Plan Failure {}\n{}'.format(LOG_HEAD, LOG_END,
                                                                                     pro_delta_plan_info))
                else:
                    logger.info('{} Provision delta plan is ongoing {}'.format(LOG_HEAD, LOG_END))
                    time.sleep(2)
            except Exception as err:
                if "Service unavailable" or "Connection refused" in str(err):
                    logger.info(
                        '{} UM service is not available or Connection refused due to NE reset, '
                        'retry 2min later {}'.format(LOG_HEAD, LOG_END)
                    )
                else:
                    logger.info('{} Get provision delta plan status failure {}'.format(LOG_HEAD, LOG_END))
                    logger.info(str(err))
                time.sleep(120)
        raise Exception('Delta commissioning failed in the given 300s. The status is {}'.format(pro_delta_plan_info))

    def fast_delta_commissioning(self, delta_data, use_m2m=True, conn_alias='default',
                                 timeout_4_provision_finished=120):
        pro_delta_ope_id = self.cu.provision_vcu_delta_plan(mo_info_list=delta_data,
                                                            use_m2m=use_m2m,
                                                            connection=conn_alias)['id']
        self._provision_vcu_delta_plan(operation_id=pro_delta_ope_id,
                                       use_m2m=use_m2m,
                                       conn_alias=conn_alias,
                                       timeout=time_to_seconds(timeout_4_provision_finished))

    def generate_dela_plan_file(self, delta_plan_name='DELTA-PLAN-1', conn_alias='default',
                                timeout_4_rest_ope_finished=30):
        delta_plan_list = self.cu.get_delta_plan_list(connection=conn_alias)
        if len(delta_plan_list) == 1:
            self.cu.delete_delta_plan(plan_id=delta_plan_list[0]['plan_id'], connection=conn_alias)
            logger.info(
                '{} Delta plan already existed in the current vcu, it is deleted successfully {}'.format(LOG_HEAD,
                                                                                                         LOG_END))
            if len(self.cu.get_delta_plan_list(connection=conn_alias)) != 0:
                raise Exception('Deleting delta plan failed')
        gen_delta_act_id = self.cu.generate_delta_plan(plan_name=delta_plan_name,
                                                       connection=conn_alias)['action_id']
        self._validate_gen_delta_plan_status(action_id=gen_delta_act_id, conn_alias=conn_alias,
                                             timeout=time_to_seconds(timeout_4_rest_ope_finished))

    def get_mo_uuid(self, mo_dn, conn_alias='default'):
        delta_plan_id = self.cu.get_delta_plan_list(connection=conn_alias)[0]['plan_id']
        delta_plan_tree = self.cu.get_delta_plan_tree_diff(plan_id=delta_plan_id, connection=conn_alias)['created']
        name_list = mo_dn.split('/')
        parent_mouuid = ''
        for name in name_list:
            for mo_info in delta_plan_tree:
                if mo_info['parent_mo_uuid'] is None:
                    parent_mo_in_plan = ''
                else:
                    parent_mo_in_plan = mo_info['parent_mo_uuid']
                if parent_mo_in_plan == parent_mouuid and mo_info['name'] == name:
                    parent_mouuid = mo_info['mo_uuid']
                    break
        return parent_mouuid

    def get_class_nidd(self, class_name, conn_alias='default'):
        all_nidds_definition = self.cu.get_nidd(connection=conn_alias)
        for nidd_definition in all_nidds_definition:
            if nidd_definition['class_name'] == class_name:
                return nidd_definition['nidd_id']

    def _verify_create_vcu_deltaplan_mo_status(self, action_id, plan_id, expect_status='success',
                                               conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            status = self.cu.get_create_managed_object_action_result(action_id=action_id,
                                                                     plan_id=plan_id,
                                                                     connection=conn_alias)['status']
            if status == expect_status:
                logger.info('{} The status of create vdu MO for delta plan is as expected - {} {}'.format(LOG_HEAD,
                                                                                                          expect_status,
                                                                                                          LOG_END))
                return
            else:
                time.sleep(2)
        raise Exception(
            'The status of create vdu MO for delta plan not match the expected. The real status is {}'.format(status))

    def create_managed_object_for_delta_plan(self, parent_mo_dn, mo_name, include_defaults=True,
                                             conn_alias='default', timeout_4_rest_ope_finished=30):
        """
        MRBTS-2345/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV6-2

        :param str parent_mo_dn: MRBTS-2345/TNLSVC-1/TNL-1/IPNO-1/IPIF-1
        :param str mo_name: IPADDRESSV6-2
        :param boolean include_defaults: default is true
        :param conn_alias:
        :return:
        """
        delta_plan_id = self.cu.get_delta_plan_list(connection=conn_alias)[0]['plan_id']
        parent_mo_uuid = self.get_mo_uuid(mo_dn=parent_mo_dn, conn_alias=conn_alias)
        class_nidd = self.get_class_nidd(class_name=mo_name.split('-')[0], conn_alias=conn_alias)
        isinstance_id = int(mo_name.split('-')[-1])
        create_mo_res = self.cu.create_managed_object_of_delta_plan(plan_id=delta_plan_id,
                                                                    parent_mo_uuid=parent_mo_uuid,
                                                                    nidd_id=class_nidd,
                                                                    instance_id=isinstance_id,
                                                                    include_defaults=include_defaults,
                                                                    connection=conn_alias)
        self._verify_create_vcu_deltaplan_mo_status(action_id=create_mo_res['action_id'],
                                                    plan_id=delta_plan_id,
                                                    conn_alias=conn_alias,
                                                    timeout=time_to_seconds(timeout_4_rest_ope_finished))

    def update_parameter_for_delta_plan(self, mo_dn, parameter_change_list,
                                        expect_status='success', conn_alias='default',
                                        timeout_4_rest_ope_finished=30):
        """

        :param str mo_dn: MRBTS-1234/NRBTS-1234/NRCELL-1
        :param list parameter_change_list: list of dicts containing parameter change data:

            :param str operation_type: Type of operation on the provided parameter in path
                                       [add, replace, remove, revert]
            :param str parameter_path: Path of specific parameter
            :param str value: (optional) Detail value of parameter in path
            Example:
                parameter_change_list = [
                    {
                        "operation_type": "replace",
                        "parameter_path": "/maxNumOfUsersNRCell",
                        "value": "350"
                    }
                ]

        :param expect_status:
        :param conn_alias:
        :return:
        """
        delta_plan_id = self.cu.get_delta_plan_list(connection=conn_alias)[0]['plan_id']
        mo_uuid = self.get_mo_uuid(mo_dn=mo_dn, conn_alias=conn_alias)
        update_para_act_id = self.cu.update_parameters_of_delta_plan(plan_id=delta_plan_id,
                                                                     mo_uuid=mo_uuid,
                                                                     parameter_change_list=parameter_change_list,
                                                                     connection=conn_alias)['action_id']
        self._verify_update_param_for_delta_plan_action(plan_id=delta_plan_id,
                                                        action_id=update_para_act_id,
                                                        expect_status=expect_status,
                                                        conn_alias=conn_alias,
                                                        timeout=time_to_seconds(timeout_4_rest_ope_finished))

    def _verify_update_param_for_delta_plan_action(self, plan_id, action_id, expect_status='success',
                                                   conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            res = self.cu.get_action_state_of_updating_parameters_of_delta_plan(plan_id=plan_id,
                                                                                action_id=action_id,
                                                                                connection=conn_alias)
            if res['status'] == expect_status:
                logger.info(
                    '{} The action status of updating vdu parameter for delta plan is as expected - {} {}'.format(
                        LOG_HEAD, expect_status, LOG_END))
                return
            else:
                time.sleep(2)
        raise Exception(
            'The real status is {} which does not match the expected. Error message is {}'.format(
                res['status'], res.get('error_message', '')))

    def validate_delta_plan(self, expect_status='success', conn_alias='default', timeout_4_rest_ope_finished=30):
        delta_plan_id = self.cu.get_delta_plan_list(connection=conn_alias)[0]['plan_id']
        validate_act_id = self.cu.validate_delta_plan(plan_id=delta_plan_id,
                                                      connection=conn_alias)['action_id']
        # TODO: fixing validation error can be added, using try ... expect ...
        self._verify_validate_delta_plan_action(delta_plan_id=delta_plan_id,
                                                action_id=validate_act_id,
                                                expect_status=expect_status,
                                                conn_alias=conn_alias,
                                                timeout=time_to_seconds(timeout_4_rest_ope_finished))
        endtime = time.time() + timeout_4_rest_ope_finished
        while time.time() < endtime:
            try:
                validation_result = self.cu.get_latest_validation_result_of_delta_plan(
                    plan_id=delta_plan_id,
                    connection=conn_alias
                )
                logger.info('{} The validation result of delta plan is: {}'.format(LOG_HEAD, validation_result))
                return
            except Exception:
                time.sleep(2)
        logger.error(
            '{} Can not get the validation result for the delta plan in the give time {}'.format(
                LOG_HEAD, timeout_4_rest_ope_finished
            )
        )

    def activate_delta_plan(self, force_reset=True, auto_lock_cells=True,
                            conn_alias='default', timeout_4_rest_ope_finished=300):
        delta_plan_id = self.cu.get_delta_plan_list(connection=conn_alias)[0]['plan_id']
        activate_act_id = self.cu.activate_delta_plan(plan_id=delta_plan_id,
                                                      force_reset=force_reset,
                                                      auto_lock_cells=auto_lock_cells,
                                                      connection=conn_alias)['operation_id']
        self._verify_activate_delta_plan_action(delta_plan_id, activate_act_id, conn_alias=conn_alias,
                                                timeout=time_to_seconds(timeout_4_rest_ope_finished))

    def _verify_validate_delta_plan_action(self, delta_plan_id, action_id, expect_status='success',
                                           conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            status = self.cu.get_action_state_of_validating_delta_plan(plan_id=delta_plan_id,
                                                                       action_id=action_id,
                                                                       connection=conn_alias)['status']
            if status == expect_status:
                logger.info('{} The action status of validating vcu delta plan is as expected - {} {}'.format(
                    LOG_HEAD, expect_status, LOG_END))
                return
            else:
                time.sleep(2)
        raise Exception(
            'The status of validating delta plan not matched the expected status. The real status is {}'.format(status))

    def _verify_activate_delta_plan_action(self, delta_plan_id, action_id, conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            try:
                act_delta_plan_info = self.cu.get_operation_state_of_activating_delta_plan(plan_id=delta_plan_id,
                                                                                           operation_id=action_id,
                                                                                           connection=conn_alias)
                act_delta_plan_status = act_delta_plan_info['status']
                if act_delta_plan_status == 'success':
                    logger.info('{} Delta plan is activated successfully {}'.format(LOG_HEAD, LOG_END))
                    return
                elif act_delta_plan_status == 'failure':
                    raise Exception('{} Activating delta Plan Failure {}\n{}'.format(LOG_HEAD, LOG_END,
                                                                                     act_delta_plan_status))
                else:
                    logger.info('{} Activating delta plan is ongoing {}'.format(LOG_HEAD, LOG_END))
                    time.sleep(2)
            except Exception as err:
                if "service unavailable" or "connection refused" in str(err).lower():
                    logger.info(
                        '{} UM service is not available or Connection refused due to NE reset, '
                        'will retry in 2min {}'.format(LOG_HEAD, LOG_END))
                    logger.info(str(err))
                else:
                    logger.info('{} Get activating delta plan status failure {}'.format(LOG_HEAD, LOG_END))
                    logger.info(str(err))
                time.sleep(120)

        raise Exception(
            'The action status of activating vcu delta plan is not successful in given timeout')

    def get_parameter_value_from_current_plan(self, mo_dn, parameter_path, conn_alias='default'):
        para_name = parameter_path.strip().split('/')[-1]
        paras_info = self.cu.search_parameters_of_current_plan(parameter_name=para_name, connection=conn_alias)
        return vCUCM.get_expected_parameter_value(paras_info, mo_dn, parameter_path)

    @staticmethod
    def get_expected_parameter_value(paras_info, dn, para_struct_path):
        """
        This keyword is used to get the expected parameter value from all of the output of searching parameters
        by the given MO distname ane parameters path.

        :param paras_info: all parameter info returned by taf kw search_parameters_of_current_plan
        :param str dn: the MO distname that the parameter belonged to, e.g, MRBTS-52/NRBTS-1/NRCELL-1
        :param str para_struct_path: parameter path, like a2ThresholdRedirectSsbRsrp/0/a2MeasRedirectSsbRsrp
        :return: parameter value, if it's simple or complex parameter, returns string type
                 if it's a simple list type parameter, it will return a list.
        """
        para_struct_list = para_struct_path.split('/')
        items = paras_info["items"]
        for item in items:
            if item["distname"] == dn and item['parameter_name'] == para_struct_list[0]:
                para_info = item["parameter"]
                para_type = item["parameter"]["parameter_type"]
                if para_type == "simple":
                    return vCUCM._get_simple_parameter_value(para_info)
                elif para_type == "complex":
                    return vCUCM._get_complex_parameter_value(para_info, para_struct_list)
                elif para_type == "simpleList":
                    return vCUCM._get_simple_list_parameter_value(para_info)
                else:
                    logger.error(
                        "{} Parameter type is not simple or complex or simpleList {}".format(LOG_HEAD, LOG_END))

    @staticmethod
    def _get_simple_parameter_value(para_info):
        # if item_info["parameter"]["simple_parameter"]["name"] == para_name:
        simple_value = para_info["simple_parameter"]
        if 'value' in simple_value.keys():
            return simple_value["value"]

    @staticmethod
    def _get_complex_parameter_value(para_info, para_struct_list):
        complex_para_value = para_info['complex_parameter']['value'][int(para_struct_list[1])]

        for struct_para in complex_para_value.structure_parameters:
            if struct_para.parameter_type == 'simple' \
                    and struct_para.simple_parameter.name == para_struct_list[-1] \
                    and hasattr(struct_para.simple_parameter, 'value'):
                return struct_para.simple_parameter.value
            if struct_para.parameter_type == 'simpleList' \
                    and struct_para.simple_list_parameter.name == para_struct_list[-1] \
                    and hasattr(struct_para.simple_list_parameter, 'value'):
                return struct_para.simple_list_parameter.value

    @staticmethod
    def _get_simple_list_parameter_value(para_info):
        # if item_info["parameter"]["simple_list_parameter"]["name"] == para_name:
        simple_list_value = para_info["simple_list_parameter"]
        if 'value' in simple_list_value.keys():
            return simple_list_value["value"]

    def get_mo_parameters_of_current_plan(self, dist_name, conn_alias='default'):
        return self.cu.get_parameters(dist_name=dist_name, connection=conn_alias)

    def get_complex_parameter_maxoccurs_from_nidd(self, class_name, param_name, conn_alias='default'):
        nidd_info = self.cu.get_nidd(connection=conn_alias)
        mo = list(filter(lambda x: x['class_name'] == class_name, nidd_info))
        params = mo[0]['parameters']
        for p_name, p_def in params.items():
            if p_name == param_name:
                try:
                    return int(p_def["complex_parameter_def"]["max_occurs"])
                except KeyError:
                    return int(p_def["simple_list_parameter_def"]["max_occurs"])
        raise Exception('Can not find the parameter {} under {}'.format(param_name, class_name))

